#!/usr/bin/env bun
// procedure.ts — the asserted-tree PDF twin: a ten-page calculation procedure in the shape of a methodological tool
// (cover with labels and a version designator, a table of contents, numbered headings at three levels, numbered
// paragraphs, four labelled equations each followed by a "Where:" definition list, a grid table, key-value parameter
// tables under the term's keys, a list with (a) items, a figure with a caption, a footnote, a revision history, a
// metadata block, an end mark, running header and footer as chrome) — fictional content, generated by this script.
//
// One model drives both outputs: the typst source (`../procedure.typ`, rendered to `../procedure.pdf` with typst) and
// the pass lines (`../../passes/<blake3>.p1.jsonl`), whose boxes are read back off the rendered PDF with
// `pdf.words@1`: every block is located by its own words in the page's word stream, so re-rendering means re-running
// this script, not re-authoring four hundred lines. The committed PDF is what the manifest's blake3 pins.
//
//   bun testdata/synthetic/gen/procedure.ts [--no-render]   (typst 0.15 on PATH; fonts are typst's bundled ones)
import { existsSync, mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fmt } from "../../../ath/packages/engine/src/address/address.ts";
import { allPages, detectChrome, isChromeWord, type PageWords, type Word } from "../../../ath/packages/engine/src/formats/pdf/words.ts";
import { squash } from "../../../ath/packages/engine/src/norm/text.ts";
import { blake3Hex, short as bodyRev } from "../../../ath/packages/kit/src/hash.ts";

const HERE = dirname(Bun.fileURLToPath(import.meta.url));
const SYN = join(HERE, "..");
const TYP = join(SYN, "procedure.typ");
const PDF = join(SYN, "procedure.pdf");
const PASSES = join(SYN, "..", "passes");

// ── the model ──────────────────────────────────────────────────────────────────────────────────────────────────────

/** A symbol in three spellings: typst math, TeX (the reading), and the plain run pdfium yields (for locating). */
interface Sym {
  typ: string;
  tex: string;
  plain: string;
}
const sym = (typ: string, tex: string, plain: string): Sym => ({ typ, tex, plain });

const Q = sym("Q_(L,k,y)", "Q_{L,k,y}", "QL,k,y");
const A = sym("A_(i,k,y)", "A_{i,k,y}", "Ai,k,y");
const U = sym("U_(i,y)", "U_{i,y}", "Ui,y");
const DT = sym("Delta T_(i,y)", "\\Delta T_{i,y}", "ΔTi,y");
const H = sym("h_(i,y)", "h_{i,y}", "hi,y");
const EPS = sym("epsilon_(i)", "\\epsilon_{i}", "εi");
const SIG = sym("sigma", "\\sigma", "σ");
const TS = sym("T_(s,i,y)", "T_{s,i,y}", "Ts,i,y");
const TA = sym("T_(a,y)", "T_{a,y}", "Ta,y");
const QT = sym("Q_(T,y)", "Q_{T,y}", "QT,y");
const QU = sym("Q_(U,y)", "Q_{U,y}", "QU,y");
const UNC = sym("u_(y)", "u_{y}", "uy");
const HOURS = sym("t_(y)", "t_{y}", "ty");

type Block =
  | { kind: "heading"; num: string; level: 1 | 2; text: string }
  | { kind: "para"; num: string; text: string; footnote?: { mark: string; text: string } }
  | { kind: "equation"; n: number; typ: string; tex: string; plain: string }
  | { kind: "where"; defs: { sym: Sym; text: string }[] }
  | { kind: "table"; caption: string; header: string[]; rows: (string | Sym)[][] }
  | { kind: "ptable"; kv: [string, string | Sym][] }
  | { kind: "list"; items: { mark: string; text: string }[] }
  | { kind: "figure"; labels: string[]; caption: string }
  | { kind: "revisions"; rows: [string, string, string][] }
  | { kind: "metadata"; kv: [string, string][] };

const ORG = "Harbour Standards Office";
const SERIES = "Calculation procedure HL-02";
const TITLE = "Procedure to estimate heat loss from insulated pipework over a reporting period";
