// ── typst ──────────────────────────────────────────────────────────────────────────────────────────────────────────

const esc = (s: string) => s.replace(/([\\#$@*_`<>])/g, "\\$1").replace(/^(\d+)\./, "$1\\.").replace(/^-/, "\\-");
const cell = (v: string | Sym) => (typeof v === "string" ? `[${esc(v)}]` : `[$${v.typ}$]`);

function typst(): string {
  const out: string[] = [];
  out.push(`// procedure.typ — generated by testdata/synthetic/gen/procedure.ts; edit the generator, not this file.`);
  out.push(`#set document(title: "${TITLE}", author: "${ORG}", date: none)`);
  out.push(`#set page(paper: "a4", margin: (x: 3cm, y: 3cm),`);
  out.push(`  header: text(size: 9pt)[${esc(SERIES)} #h(1fr) ${esc(ORG)}],`);
  out.push(`  footer: text(size: 9pt)[Version ${VERSION} #h(1fr) Page #context counter(page).display() of #context counter(page).final().first()])`);
  out.push(`#set text(font: "Libertinus Serif", size: 12pt, hyphenate: false)`);
  out.push(`#show math.equation: set text(font: "New Computer Modern Math")`);
  out.push(`#set par(justify: false, leading: 0.75em, spacing: 1.1em)`);
  out.push(`#set heading(numbering: none)`);
  out.push(`#show heading.where(level: 1): it => { v(10pt); text(size: 14pt, weight: "bold", it.body); v(4pt) }`);
  out.push(`#show heading.where(level: 2): it => { v(6pt); text(size: 12pt, weight: "bold", it.body); v(2pt) }`);
  out.push(`#set table(inset: (x: 6pt, y: 4pt))`);
  // cover
  for (const [i, l] of cover.labels.entries()) {
    out.push(`#text(size: ${i === 0 ? 10 : i === 1 ? 13 : 18}pt, weight: "bold")[${esc(l)}]`);
    out.push(i === 0 ? "#v(2cm)" : i === 1 ? "#v(6cm)" : "#v(1cm)");
  }
  out.push(`#text(size: 22pt, weight: "bold")[${esc(cover.title)}]`);
  out.push("#v(2cm)");
  out.push(`#text(size: 11pt)[${esc(cover.version)}]`);
  out.push(
    `#place(bottom + left, rect(width: ${cover.figure.w}cm, height: ${cover.figure.h}cm, stroke: 1pt, inset: 8pt, align(center + horizon, text(size: 20pt, weight: "bold")[${cover.figure.text}])))`,
  );
  out.push("#pagebreak()");
  // toc
  out.push(`#text(size: 14pt, weight: "bold")[Table of contents]`);
  out.push("#v(6pt)");
  out.push(`#outline(title: none, indent: 1.5em)`);
  out.push("#pagebreak()");
  // body
  let fig = 0;
  let ptNo = 0;
  for (const b of body) {
    switch (b.kind) {
      case "heading":
        out.push(`${b.level === 1 ? "=" : "=="} ${esc(`${b.num} ${b.text}`)}`);
        break;
      case "para":
        out.push("", `${esc(b.num)} ${esc(b.text)}${b.footnote ? `#footnote[${esc(b.footnote.text)}]` : ""}`, "");
        break;
      case "equation":
        out.push(`#grid(columns: (1fr, auto), align: (center + horizon, right + horizon), $ ${b.typ} $, [Equation (${b.n})])`);
        break;
      case "where":
        out.push("", "Where:", "");
        out.push(`#table(columns: (auto, auto, 1fr), stroke: none, inset: (x: 4pt, y: 3pt),`);
        for (const d of b.defs) out.push(`  [$${d.sym.typ}$], [=], [${esc(d.text)}],`);
        out.push(")");
        break;
      case "table":
        out.push(`#figure(table(columns: (auto, auto, 1fr), align: left,`);
        out.push(`  ${b.header.map((h) => `[*${esc(h)}*]`).join(", ")},`);
        for (const r of b.rows) out.push(`  ${r.map(cell).join(", ")},`);
        out.push(`), caption: [${esc(b.caption)}], kind: table, supplement: [Table])`);
        break;
      case "ptable":
        ptNo++;
        out.push("", `*Data / Parameter table ${ptNo}.*`, "");
        out.push(`#table(columns: (46%, 1fr), align: left,`);
        for (const [k, v] of b.kv) out.push(`  [${esc(k)}], ${cell(v)},`);
        out.push(")");
        break;
      case "list":
        out.push("");
        for (const it of b.items) out.push(`#grid(columns: (2em, 1fr), [${esc(it.mark)}], [${esc(it.text)}])`, "#v(3pt)");
        break;
      case "figure":
        fig++;
        out.push(
          `#figure(rect(width: 80%, height: 2.4cm, stroke: 1pt, inset: 10pt, align(horizon, [${b.labels.map(esc).join(" #h(1fr) ")}])), caption: [${esc(b.caption)}])`,
        );
        break;
      case "revisions":
        out.push("", "Revision history:", "");
        out.push(`#table(columns: (auto, auto, 1fr), align: left,`);
        out.push(`  [*Version*], [*Date*], [*Description*],`);
        for (const r of b.rows) out.push(`  ${r.map(cell).join(", ")},`);
        out.push(")");
        break;
      case "metadata":
        out.push("", "#v(10pt)");
        out.push(`#table(columns: (auto, 1fr), stroke: none, inset: (x: 4pt, y: 2pt),`);
        for (const [k, v] of b.kv) out.push(`  [${esc(k)}:], [${esc(v)}],`);
        out.push(")");
        break;
    }
  }
  out.push("", "#v(1cm)", "#align(center)[\\- \\- \\- \\- \\-]", "");
  return `${out.join("\n")}\n`;
}

// ── locating blocks in the rendered pages ──────────────────────────────────────────────────────────────────────────

type Box = [number, number, number, number];
interface Hit {
  page: number;
  words: Word[];
}

const sq = (s: string) => squash(s);

function union(words: readonly Word[]): Box {
  const x0 = Math.min(...words.map((w) => w.bbox[0]));
  const y0 = Math.min(...words.map((w) => w.bbox[1]));
  const x1 = Math.max(...words.map((w) => w.bbox[0] + w.bbox[2]));
  const y1 = Math.max(...words.map((w) => w.bbox[1] + w.bbox[3]));
  return [x0, y0, x1 - x0, y1 - y0];
}
const boxAt = (page: number, b: Box) => `page=${page}&bbox=${b.map(fmt).join(",")}`;

/** The address of a set of words: one box per page, a union when they span pages. */
function addressOf(hits: Hit[]): string {
  const byPage = new Map<number, Word[]>();
  for (const h of hits) byPage.set(h.page, [...(byPage.get(h.page) ?? []), ...h.words]);
  return [...byPage.entries()]
    .sort((a, b) => a[0] - b[0])
    .map(([p, ws]) => boxAt(p, union(ws)))
    .join(";");
}

class Locator {
  private cursor = 0; // a running position over the concatenation of all pages, so repeated texts resolve in order
  private streams: { page: number; words: Word[]; sq: string[]; offsets: number[]; text: string }[] = [];
  constructor(public pages: PageWords[]) {
    // the running header and footer are chrome: derived by the engine, never a scope, so never a hit
    const chrome = detectChrome(pages);
    for (const p of pages) {
      const words = p.words.filter((w) => !isChromeWord(chrome, p.page, w));
      const sqs = words.map((w) => sq(w.text));
      const offsets: number[] = [];
      let text = "";
      for (const s of sqs) {
        offsets.push(text.length);
        text += s;
      }
      this.streams.push({ page: p.page, words, sq: sqs, offsets, text });
    }
  }
  /** The words carrying `text`, searched forward from the cursor; throws when absent. */
  find(text: string, opts: { advance?: boolean } = {}): Hit {
    const needle = sq(text);
    if (!needle) throw new Error(`nothing to find in ${JSON.stringify(text)}`);
    let seen = 0;
    for (const s of this.streams) {
      const from = Math.max(0, this.cursor - seen);
      if (from < s.text.length) {
        const i = s.text.indexOf(needle, from);
        if (i !== -1) {
          const first = s.offsets.findLastIndex((o) => o <= i);
          const last = s.offsets.findLastIndex((o) => o < i + needle.length);
          const words = s.words.slice(first, last + 1);
          if (opts.advance !== false) this.cursor = seen + i + needle.length;
          return { page: s.page, words };
        }
      }
      seen += s.text.length;
    }
    throw new Error(`not found after cursor: ${JSON.stringify(text)}`);
  }
  /** The run of dash-only words at the end (the squash drops dashes, so the end mark is found by its words). */
  endMark(): Hit {
    for (let i = this.pages.length - 1; i >= 0; i--) {
      const p = this.pages[i]!;
      const dashes = p.words.filter((w) => /^[-\u2010-\u2015]$/.test(w.text));
      if (dashes.length >= 3) return { page: p.page, words: dashes };
    }
    throw new Error("no end mark");
  }
  /** Every word on the page sharing the vertical band of `hit` (a table row's other cells, a label on the same line). */
  band(hit: Hit, opts: { left?: number; right?: number } = {}): Hit {
    const b = union(hit.words);
    const words = this.streams[hit.page - 1]!.words.filter((w) => {
      const cy = w.bbox[1] + w.bbox[3] / 2;
      if (cy < b[1] - 0.002 || cy > b[1] + b[3] + 0.002) return false;
      if (opts.left !== undefined && w.bbox[0] + w.bbox[2] / 2 < opts.left) return false;
      if (opts.right !== undefined && w.bbox[0] + w.bbox[2] / 2 > opts.right) return false;
      return true;
    });
    return { page: hit.page, words };
  }
}

// ── the pass ───────────────────────────────────────────────────────────────────────────────────────────────────────

type Line = Record<string, unknown>;

async function pass(pages: PageWords[]): Promise<{ lines: Line[]; headingPages: Map<string, number> }> {
  const L = new Locator(pages);
  const lines: Line[] = [];
  const ords = new Map<string, number>();
  const place = (at: string, parent: string) => {
    const ord = ords.get(parent) ?? 0;
    ords.set(parent, ord + 1);
    lines.push({ at, predicate: "in", value: { at: parent, ord } });
  };
  const manifests = (at: string, term: string, fields: Line = {}) => lines.push({ at, predicate: "manifests", term, ...fields });
  const reads = async (at: string, aspect: "text" | "cells" | "tex", body: unknown) =>
    lines.push({ at, predicate: "reads_as", aspect, rev: await bodyRev(body), body });

  manifests("whole", "methodological-tool", { version: VERSION });
  for (const p of pages) manifests(`page=${p.page}`, "page");

  // cover
  manifests("page=1", "cover-page");
  place("page=1", "whole");
  for (const l of cover.labels) {
    const h = L.find(l);
    const at = addressOf([h]);
    manifests(at, "label");
    place(at, "page=1");
    await reads(at, "text", l);
  }
  {
    const h = L.find(cover.title);
    const at = addressOf([h]);
    manifests(at, "heading", { level: 0 });
    place(at, "page=1");
    await reads(at, "text", cover.title);
    const v = L.find(cover.version);
    const vat = addressOf([v]);
    manifests(vat, "label");
    place(vat, "page=1");
    await reads(vat, "text", cover.version);
    // the figure is placed, not flowed: its box follows from the page geometry (A4, 2.5 cm margins)
    const W = 595.276;
    const Hh = 841.89;
    const cm = 28.3465;
    const fb: Box = [(3 * cm) / W, (Hh - 3 * cm - cover.figure.h * cm) / Hh, (cover.figure.w * cm) / W, (cover.figure.h * cm) / Hh];
    const fat = boxAt(1, fb);
    manifests(fat, "figure");
    place(fat, "page=1");
    L.find(cover.figure.text); // consume the logo text so later searches start past it
  }
  // table of contents
  manifests("page=2", "table-of-contents");
  place("page=2", "whole");
  {
    // the title is the first row of the toc, as a table of contents reads (cells: num, title, page)
    const entries: Hit[] = [L.find("Table of contents")];
    const rows: string[][] = [["Table of contents", "", ""]];
    for (const b of body) {
      if (b.kind !== "heading") continue;
      const h = L.band(L.find(`${b.num} ${b.text}`), { left: 0.1 });
      entries.push(h);
      const pageWord = h.words[h.words.length - 1]!.text.replace(/\u2060/g, "");
      rows.push([b.num, b.text, pageWord]);
    }
    const at = addressOf([{ page: 2, words: entries.flatMap((e) => e.words) }]);
    manifests(at, "toc");
    place(at, "page=2");
    await reads(at, "cells", rows);
  }
  // body
  const headingPages = new Map<string, number>();
  const stack: { level: number; at: string }[] = [];
  const parent = () => (stack.length ? stack[stack.length - 1]!.at : "whole");
  let tableNo = 0;
  let figNo = 0;
  let ptNo = 0;
  for (const b of body) {
    switch (b.kind) {
      case "heading": {
        const h = L.find(`${b.num} ${b.text}`);
        const at = addressOf([h]);
        while (stack.length && stack[stack.length - 1]!.level >= b.level) stack.pop();
        manifests(at, "heading", { num: b.num, level: b.level });
        place(at, parent());
        await reads(at, "text", b.text);
        headingPages.set(b.num, h.page);
        stack.push({ level: b.level, at });
        break;
      }
      case "para": {
        const h = L.find(`${b.num} ${b.text}`);
        const at = addressOf([h]);
        manifests(at, "paragraph", { num: b.num });
        place(at, parent());
        await reads(at, "text", b.footnote ? `${b.text}[^${b.footnote.mark}]` : b.text);
        if (b.footnote) {
          const f = L.find(b.footnote.text, { advance: false });
          const fh = L.band(f, { left: 0.1 }); // the mark and the note
          const fat = addressOf([fh]);
          manifests(fat, "footnote", { mark: b.footnote.mark });
          place(fat, parent());
          await reads(fat, "text", b.footnote.text);
        }
        break;
      }
      case "equation": {
        const h = L.find(b.plain);
        const label = L.find(`Equation (${b.n})`);
        const at = addressOf([{ page: h.page, words: [...h.words, ...label.words] }]);
        manifests(at, "equation", { label: `Equation (${b.n})` });
        place(at, parent());
        await reads(at, "tex", b.tex);
        break;
      }
      case "where": {
        const w = L.find("Where:");
        const wat = addressOf([w]);
        manifests(wat, "paragraph");
        place(wat, parent());
        await reads(wat, "text", "Where:");
        const rows: { hit: Hit; cells: string[] }[] = [];
        for (const d of b.defs) {
          const h = L.band(L.find(`${d.sym.plain} = ${d.text}`), { left: 0.1 });
          rows.push({ hit: h, cells: [`$${d.sym.tex}$`, "=", d.text] });
        }
        const lat = addressOf(rows.map((r) => r.hit));
        manifests(lat, "definition-list");
        place(lat, parent());
        for (const r of rows) {
          const at = addressOf([r.hit]);
          manifests(at, "definition");
          place(at, lat);
          await reads(at, "cells", r.cells);
        }
        break;
      }
      case "table": {
        tableNo++;
        const header = L.band(L.find(b.header.join(" ")), { left: 0.1 });
        const rows: { hit: Hit; cells: string[] }[] = [{ hit: header, cells: b.header }];
        for (const r of b.rows) {
          const plain = r.map((c) => (typeof c === "string" ? c : c.plain)).join(" ");
          rows.push({ hit: L.band(L.find(plain), { left: 0.1 }), cells: r.map((c) => (typeof c === "string" ? c : `$${c.tex}$`)) });
        }
        const cap = L.find(`Table ${tableNo}: ${b.caption}`);
        const tat = addressOf([...rows.map((r) => r.hit), cap]);
        manifests(tat, "table", { layout: "grid" });
        place(tat, parent());
        const cat = addressOf([cap]);
        manifests(cat, "caption");
        place(cat, tat);
        await reads(cat, "text", `Table ${tableNo}: ${b.caption}`);
        for (const r of rows) {
          const at = addressOf([r.hit]);
          manifests(at, "row");
          place(at, tat);
          await reads(at, "cells", r.cells);
        }
        break;
      }
      case "ptable": {
        ptNo++;
        const capText = `Data / Parameter table ${ptNo}.`;
        const cap = L.find(capText);
        const rows: { hit: Hit; cells: string[] }[] = [];
        for (const [k, v] of b.kv) {
          const plain = typeof v === "string" ? v : v.plain;
          const h = L.band(L.find(`${k} ${plain}`), { left: 0.1 });
          rows.push({ hit: h, cells: [k, typeof v === "string" ? v : `$${v.tex}$`] });
        }
        const tat = addressOf([cap, ...rows.map((r) => r.hit)]);
        manifests(tat, "parameter-table", { layout: "key-value", num: String(ptNo) });
        place(tat, parent());
        const cat = addressOf([cap]);
        manifests(cat, "caption");
        place(cat, tat);
        await reads(cat, "text", capText);
        for (const r of rows) {
          const at = addressOf([r.hit]);
          manifests(at, "row");
          place(at, tat);
          await reads(at, "cells", r.cells);
        }
        break;
      }
      case "list": {
        const items: { hit: Hit; mark: string; text: string }[] = [];
        for (const it of b.items) items.push({ hit: L.find(`${it.mark} ${it.text}`), mark: it.mark, text: it.text });
        const lat = addressOf(items.map((i) => i.hit));
        manifests(lat, "list");
        place(lat, parent());
        for (const it of items) {
          const at = addressOf([it.hit]);
          manifests(at, "list-item", { num: it.mark });
          place(at, lat);
          await reads(at, "text", it.text);
        }
        break;
      }
      case "figure": {
        figNo++;
        const inner = L.find(b.labels.join(" "));
        const cap = L.find(`Figure ${figNo}: ${b.caption}`);
        const fat = addressOf([inner]);
        manifests(fat, "figure");
        place(fat, parent());
        const cat = addressOf([cap]);
        manifests(cat, "caption");
        place(cat, fat);
        await reads(cat, "text", `Figure ${figNo}: ${b.caption}`);
        break;
      }
      case "revisions": {
        const lead = L.find("Revision history:");
        const lat = addressOf([lead]);
        manifests(lat, "paragraph");
        place(lat, parent());
        await reads(lat, "text", "Revision history:");
        const rows: { hit: Hit; cells: string[] }[] = [{ hit: L.band(L.find("Version Date Description"), { left: 0.1 }), cells: ["Version", "Date", "Description"] }];
        for (const r of b.rows) rows.push({ hit: L.band(L.find(r.join(" ")), { left: 0.1 }), cells: r });
        const tat = addressOf(rows.map((r) => r.hit));
        manifests(tat, "revision-history", { layout: "grid" });
        place(tat, parent());
        for (const r of rows) {
          const at = addressOf([r.hit]);
          manifests(at, "row");
          place(at, tat);
          await reads(at, "cells", r.cells);
        }
        break;
      }
      case "metadata": {
        const hits = b.kv.map(([k, v]) => L.find(`${k}: ${v}`));
        const at = addressOf([{ page: hits[0]!.page, words: hits.flatMap((h) => h.words) }]);
        manifests(at, "metadata");
        place(at, parent());
        await reads(at, "text", b.kv.map(([k, v]) => `${k}: ${v}`).join("\n"));
        break;
      }
    }
  }
  const end = L.endMark();
  const eat = addressOf([end]);
  manifests(eat, "end-mark");
  place(eat, "whole");
  await reads(eat, "text", "- - - - -");
  return { lines, headingPages };
}

// ── main ───────────────────────────────────────────────────────────────────────────────────────────────────────────

const render = !process.argv.includes("--no-render");
if (render) {
  writeFileSync(TYP, typst());
  const r = Bun.spawnSync(["typst", "compile", TYP, PDF]);
  if (r.exitCode !== 0) throw new Error(`typst: ${r.stderr.toString()}`);
}
if (!existsSync(PDF)) throw new Error(`${PDF} is not rendered; run without --no-render`);
const bytes = new Uint8Array(await Bun.file(PDF).arrayBuffer());
const pages = await allPages(bytes);
const { lines } = await pass(pages);
const blake3 = await blake3Hex(bytes);
mkdirSync(PASSES, { recursive: true });
const out = join(PASSES, `${blake3}.p1.jsonl`);
writeFileSync(out, lines.map((l) => `${JSON.stringify(l)}\n`).join(""));
const counts = new Map<string, number>();
for (const l of lines) {
  const k = l.predicate === "manifests" ? `manifests ${l.term}` : l.predicate === "reads_as" ? `reads_as ${l.aspect}` : String(l.predicate);
  counts.set(k, (counts.get(k) ?? 0) + 1);
}
console.log(`${PDF}: ${pages.length} pages, ${pages.reduce((n, p) => n + p.words.length, 0)} words, blake3 ${blake3}`);
console.log(`${out}: ${lines.length} lines`);
for (const [k, v] of [...counts.entries()].sort()) console.log(`  ${k.padEnd(28)} ${v}`);
